package com.networkmonitor.dto;
import com.networkmonitor.entity.MonitoringMetric;import java.time.LocalDateTime;
public class MetricResponseDto{private Long id,deviceId;private LocalDateTime timestamp;private boolean reachable;private Double latencyMs,packetLossPercent;public static MetricResponseDto fromEntity(MonitoringMetric m){MetricResponseDto d=new MetricResponseDto();d.id=m.getId();d.deviceId=m.getDevice().getId();d.timestamp=m.getTimestamp();d.reachable=m.isReachable();d.latencyMs=m.getLatencyMs();d.packetLossPercent=m.getPacketLossPercent();return d;}public Long getId(){return id;}public Long getDeviceId(){return deviceId;}public LocalDateTime getTimestamp(){return timestamp;}public boolean isReachable(){return reachable;}public Double getLatencyMs(){return latencyMs;}public Double getPacketLossPercent(){return packetLossPercent;}}
